"use client";

import { useEffect, useState } from "react";

export type Role = "Student" | "Teacher" | "Administrator";
type AuthMode = "login" | "signup" | null;

const studentNav = ["Dashboard","My Courses","Learning Resources","Lesson Notes","Assignments","Assessments","Practice Questions","Mock Examinations","Downloads","Results & Grades","Progress Tracking","Notifications","Messages","Profile","Settings"];
const teacherNav = ["Dashboard","My Classes","My Subjects","Student Lists","Lesson Notes","Learning Resources","Assignments","Assessments","Online Sessions","Attendance","Gradebook","Student Performance","Notifications","Messages","Profile","Settings"];
const adminNav = ["Dashboard","Student Management","Teacher Management","User Accounts","Courses","Classes","Subjects","Learning Resources","Assignments","Assessments","Timetable","Notifications","Reports","Platform Settings","Audit Logs","Profile"];

const recommended = [
  {title:"English Language",teacher:"NaCCA-aligned curriculum",level:"Core subject",duration:"Basic 4–9",tone:"violet",mark:"En"},
  {title:"Mathematics",teacher:"NaCCA-aligned curriculum",level:"Core subject",duration:"Basic 4–9",tone:"sky",mark:"Mx"},
  {title:"Integrated Science",teacher:"NaCCA-aligned curriculum",level:"Core subject",duration:"Basic 4–9",tone:"emerald",mark:"Sc"},
  {title:"Computing",teacher:"NaCCA-aligned curriculum",level:"Core subject",duration:"Basic 4–9",tone:"amber",mark:"Co"},
];

type Subject = "English" | "Mathematics" | "Science" | "Computing";
const classLevels = [4,5,6,7,8,9] as const;
const curriculum: Record<Subject, Record<number, string[]>> = {
  English:{4:["Conversation and everyday communication","Reading fluency and comprehension","Grammar: nouns, pronouns and verbs","Paragraph writing and punctuation","Creative writing and literature"],5:["Listening, speaking and presentation","Reading for meaning and inference","Grammar: tense, agreement and modifiers","Informative and narrative writing","Poetry, prose and drama"],6:["Formal and informal communication","Critical reading and summarising","Grammar and sentence structure","Essay, letter and report writing","Literature and creative response"],7:["Oral Language (Listening and Speaking)","Reading","Writing","Grammar Usage","Literature"],8:["Oral Language (Listening and Speaking)","Reading","Writing","Grammar Usage","Literature"],9:["Oral Language (Listening and Speaking)","Reading","Writing","Grammar Usage","Literature"]},
  Mathematics:{4:["Whole numbers and place value","Fractions and decimal numbers","Patterns and simple algebra","Geometry and measurement","Data collection and representation"],5:["Operations with whole numbers","Fractions, decimals and percentages","Number patterns and unknowns","Angles, shapes, perimeter and area","Data handling and probability"],6:["Number and financial applications","Ratio, fractions and percentages","Algebraic expressions and equations","Geometry, measurement and transformations","Statistics and probability"],7:["Number","Algebra","Geometry and Measurement","Data and Probability"],8:["Number","Algebra","Geometry and Measurement","Data and Probability"],9:["Number","Algebra","Geometry and Measurement","Data and Probability"]},
  Science:{4:["Diversity of living and non-living things","Cycles in nature and the water cycle","Systems: the human body and plants","Forces, energy and simple machines","Humans and the environment"],5:["Materials and their properties","Life cycles and ecosystems","Body systems and health","Electricity, light and sound","Environmental care and sustainability"],6:["Matter and mixtures","Earth, space and natural cycles","Reproduction and body systems","Energy transformation and forces","Agriculture, health and environment"],7:["Diversity of Matter","Cycles","Systems","Energy"],8:["Diversity of Matter","Cycles","Systems","Energy"],9:["Diversity of Matter","Cycles","Systems","Energy"]},
  Computing:{4:["Introduction to computing systems","Parts of a computer and input devices","Word processing and digital drawing","Internet awareness and online safety","Algorithms and step-by-step thinking"],5:["Computer hardware and storage","File management and productivity tools","Presentations and digital communication","Responsible internet use","Programming patterns and simple algorithms"],6:["Operating systems and networks","Documents, spreadsheets and presentations","Search, communication and cyber safety","Data and information","Visual programming and problem solving"],7:["Computing Systems","Information and Communication Networks","Data and Information","Algorithms and Programming"],8:["Computing Systems","Information and Communication Networks","Data and Information","Algorithms and Programming"],9:["Computing Systems","Information and Communication Networks","Data and Information","Algorithms and Programming"]},
};

function Logo(){return <div className="logo"><span>L</span><div><b>LUMA</b><small>LEARNING PLATFORM</small></div></div>}

function Landing({openAuth}:{openAuth:(role:Role,mode:Exclude<AuthMode,null>)=>void}){
  const [previewSubject,setPreviewSubject]=useState<Subject|null>(null);
  const courseSubject=(title:string):Subject=>title==="English Language"?"English":title==="Integrated Science"?"Science":title as Subject;
  return <div className="landing">
    <nav className="landing-nav"><Logo/><div className="nav-links"><a href="#home">Home</a><a href="#courses">Courses</a><a href="#features">Features</a><a href="#pricing">Pricing</a><a href="#about">About</a></div><div className="nav-actions"><button className="ghost" onClick={()=>openAuth("Student","login")}>Log in</button><button className="button" onClick={()=>openAuth("Student","signup")}>Create account</button></div></nav>
    <main>
      <section className="hero" id="home"><div className="hero-copy"><span className="pill">Standards-based learning for Ghanaian schools</span><h1>Learn smarter.<br/><em>Achieve more.</em></h1><p>A complete digital learning platform that brings students, teachers, and schools together in one beautifully simple workspace.</p><div className="hero-actions"><button className="button large" onClick={()=>openAuth("Student","signup")}>Enroll as a student <span>→</span></button><a className="outline large" href="#courses">Explore courses</a></div></div>
      <div className="hero-product"><div className="orb orb-one"/><div className="orb orb-two"/><div className="product-window"><div className="window-bar"><i/><i/><i/><span>Student learning dashboard</span></div><div className="mock-body"><aside><b>L</b>{[1,2,3,4,5].map(x=><i key={x}/>)}</aside><section><div className="mock-welcome"><div><small>YOUR WORKSPACE</small><strong>Courses, resources and assessments</strong><p>Your real enrollment data appears after sign-in.</p></div></div><div className="mock-stats"><i/><i/><i/></div><div className="mock-grid"><article><b>Course modules</b><span/><span/><span/></article><article><b>Learning resources</b></article></div></section></div></div></div></section>
      <section className="marketing" id="features"><span className="kicker">ONE PLATFORM. EVERY POSSIBILITY.</span><h2>Everything you need to<br/>move learning forward</h2><p>Purpose-built experiences for every member of your learning community.</p><div className="feature-grid"><article><span className="feature-icon violet">01</span><h3>Learn without limits</h3><p>Engaging lessons, assessments, live classes and resources that meet every learner where they are.</p><a onClick={()=>openAuth("Student","login")}>Student workspace →</a></article><article><span className="feature-icon sky">02</span><h3>Teach with confidence</h3><p>Create lessons, share resources, grade work and understand every learner’s progress in real time.</p><a onClick={()=>openAuth("Teacher","login")}>Teacher workspace →</a></article><article><span className="feature-icon emerald">03</span><h3>Lead with clarity</h3><p>Manage your entire school, monitor performance and make confident decisions from a single view.</p><a onClick={()=>openAuth("Administrator","login")}>Administrator workspace →</a></article></div></section>
      <section className="courses-section" id="courses"><div className="section-title"><div><span className="kicker">EXPLORE WHAT’S POSSIBLE</span><h2>Courses learners love</h2></div><a className="outline" href="#courses">Browse all courses →</a></div><div className="recommend-grid">{recommended.map(c=><CourseTile key={c.title} course={c} view={()=>setPreviewSubject(courseSubject(c.title))}/>)}</div></section>
      <section className="cta" id="pricing"><span className="pill light">START YOUR JOURNEY TODAY</span><h2>Brighter learning starts here.</h2><p>Join a growing community of learners, educators, and schools building what comes next.</p><button className="button light-button" onClick={()=>openAuth("Student","signup")}>Create your free account →</button></section>
    </main>
    <footer><Logo/><p>Modern learning for ambitious students, inspiring teachers, and forward-thinking schools.</p><div><a href="/about">About</a><a href="/help">Help Center</a><a href="/privacy">Privacy</a><a href="/terms">Terms</a><a href="/contact">Contact</a></div><small>© 2026 LUMA Learning Platform. All rights reserved.</small></footer>
    {previewSubject&&<CoursePreviewDialog subject={previewSubject} close={()=>setPreviewSubject(null)} login={()=>{setPreviewSubject(null);openAuth("Student","login")}}/>}
  </div>
}

function AuthDialog({role,mode,close,enter}:{role:Role;mode:Exclude<AuthMode,null>;close:()=>void;enter:(r:Role)=>void}){
  const [selected,setSelected]=useState(role);const [form,setForm]=useState({fullName:"",email:"",phone:"",password:"",confirmPassword:"",classLevel:"",acceptedTerms:false});const [busy,setBusy]=useState(false);const [error,setError]=useState("");const [success,setSuccess]=useState("");const signup=mode==="signup"&&selected==="Student";const set=(key:string,value:string|boolean)=>setForm({...form,[key]:value});const submit=async()=>{setBusy(true);setError("");const res=await fetch(signup?"/api/auth/register":"/api/auth/login",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(form)});const data=await res.json();setBusy(false);if(res.ok){if(data.status==="pending_verification"){setSuccess(data.message);return}location.replace("/portal");enter(selected)}else setError(data.error||"Request failed")};const forgot=async()=>{const address=prompt("Enter the email registered to your account:");if(!address)return;const response=await fetch("/api/auth/forgot-password",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({email:address})});const data=await response.json();if(response.ok)setSuccess(data.message);else setError(data.error)};return <div className="modal-backdrop" onMouseDown={close}><div className="auth-card" role="dialog" aria-modal="true" aria-label={`${selected} ${mode}`} onMouseDown={e=>e.stopPropagation()}><button className="modal-close" onClick={close}>×</button><Logo/><div className="role-tabs">{(["Student","Teacher","Administrator"] as Role[]).map(r=><button key={r} className={r===selected?"active":""} onClick={()=>setSelected(r)}>{r}</button>)}</div><span className="kicker">{selected.toUpperCase()} PORTAL</span><h2>{signup?"Create your student account":"Welcome back"}</h2><p>{signup?"Your account becomes active immediately after secure registration.":selected==="Teacher"?"Use the credentials issued by your administrator.":"Sign in to continue to your assigned LUMA workspace."}</p>{signup&&<><label>Full name <b className="required">*</b><input value={form.fullName} onChange={e=>set("fullName",e.target.value)} placeholder="Enter your full name"/></label><label>Phone number <b className="required">*</b><input value={form.phone} onChange={e=>set("phone",e.target.value)} placeholder="e.g. 024 000 0000"/></label><label>Class or programme <b className="required">*</b><select value={form.classLevel} onChange={e=>set("classLevel",e.target.value)}><option value="">Select your class</option>{[4,5,6,7,8,9].map(n=><option key={n}>Basic {n}</option>)}</select></label></>}<label>{selected==="Teacher"?"Username or email":"Email address"} <b className="required">*</b><input type="email" value={form.email} onChange={e=>set("email",e.target.value)} placeholder="name@example.com"/></label><label>Password <b className="required">*</b><input type="password" value={form.password} onChange={e=>set("password",e.target.value)} placeholder="Enter your password"/></label>{signup&&<><label>Confirm password <b className="required">*</b><input type="password" value={form.confirmPassword} onChange={e=>set("confirmPassword",e.target.value)} placeholder="Repeat your password"/></label><label className="terms"><input type="checkbox" checked={form.acceptedTerms} onChange={e=>set("acceptedTerms",e.target.checked)}/><span>I accept the LUMA Terms of Service, Privacy Policy, and Acceptable Use Policy. <b className="required">*</b></span></label><details className="terms-details"><summary>Read the full terms</summary><ol><li>Provide accurate and current information.</li><li>Keep account credentials confidential.</li><li>Maintain academic integrity.</li><li>Treat all users respectfully.</li><li>Use Academy resources only for personal education.</li><li>Do not share, copy, sell, or publish Academy resources or credentials.</li><li>Do not disrupt or gain unauthorized access to the platform.</li><li>Personal data is used for educational, administrative, and security purposes.</li><li>Accounts violating these terms may be suspended or disabled.</li><li>Continued use constitutes acceptance of updated terms.</li></ol><p>By selecting the checkbox, I confirm that I have read, understood, and accepted these terms.</p></details></>}<div className="auth-row">{!signup&&<label className="check"><input type="checkbox"/> Remember me</label>}<button onClick={forgot}>Forgot password?</button></div>{error&&<em className="form-error">{error}</em>}{success&&<div className="form-success">{success}</div>}<button className="button auth-submit" disabled={busy||(signup&&(!form.fullName||!form.email||!form.phone||!form.password||!form.confirmPassword||!form.classLevel||!form.acceptedTerms))} onClick={submit}>{busy?"Please wait…":signup?"Create student account":"Sign in securely"} →</button>{mode==="signup"&&selected!=="Student"&&<small className="auth-note">Teacher and administrator accounts cannot be created publicly.</small>}</div></div>
}

function CourseTile({course,view}:{course:typeof recommended[number];view:()=>void}){return <article className="recommend-card"><div className={`course-thumb ${course.tone}`}><span>{course.mark}</span></div><div className="recommend-body"><small>{course.teacher}</small><h3>{course.title}</h3><div className="course-meta"><span>{course.level}</span><span>{course.duration}</span></div><button className="outline" onClick={view}>View course</button></div></article>}

function CoursePreviewDialog({subject,close,login}:{subject:Subject;close:()=>void;login:()=>void}){
  const [level,setLevel]=useState(7);const [strand,setStrand]=useState<string|null>(null);const strands=curriculum[subject][level];
  const label=subject==="English"?"English Language":subject==="Science"?"Integrated Science":subject;
  const select=(value:string)=>{setStrand(value);requestAnimationFrame(()=>document.getElementById("strand-preview")?.scrollIntoView({behavior:"smooth",block:"nearest"}))};
  return <div className="modal-backdrop" onMouseDown={close}><section className="course-preview" role="dialog" aria-modal="true" aria-label={`${label} course preview`} onMouseDown={event=>event.stopPropagation()}><button className="modal-close" onClick={close}>×</button><span className="kicker">PUBLIC COURSE OUTLINE</span><h2>{label}</h2><p>Preview the strands and sub-strand area. Sign in to open lessons, activities and assessments.</p><div className="preview-levels">{[7,8,9].map(value=><button key={value} className={level===value?"active":""} onClick={()=>{setLevel(value);setStrand(null)}}>Basic {value}</button>)}</div><nav className="preview-strands" aria-label={`${label} strands`}>{strands.map((value,index)=><a key={value} href="#strand-preview" onClick={event=>{event.preventDefault();select(value)}}><span>{String(index+1).padStart(2,"0")}</span><b>{value}</b><em>View sub-strands →</em></a>)}</nav>{strand&&<div className="locked-strand" id="strand-preview"><span>🔒</span><div><small>BASIC {level} · {label.toUpperCase()}</small><h3>{strand}</h3><p>The sub-strands, lessons, learning resources and assessments are available to signed-in students.</p></div><button className="button" onClick={login}>Sign in to access course →</button></div>}</section></div>
}

function CurriculumBrowser(){
  const [subject,setSubject]=useState<Subject>("English");const [level,setLevel]=useState(4);const topics=curriculum[subject][level];
  const subjectMeta:Record<Subject,{mark:string,tone:string,summary:string}>={English:{mark:"En",tone:"violet",summary:"Communication, reading, writing, grammar and literature"},Mathematics:{mark:"Mx",tone:"sky",summary:"Number, algebra, geometry, measurement and data"},Science:{mark:"Sc",tone:"emerald",summary:"Scientific inquiry, life, matter, energy and the environment"},Computing:{mark:"Co",tone:"amber",summary:"Digital literacy, systems, data, safety and programming"}};
  const subjectLabel=(value:Subject)=>value==="English"?"English Language":value==="Science"?"Integrated Science":value;
  return <section className="curriculum-browser"><div className="curriculum-heading"><div><span className="kicker">GHANA STANDARDS-BASED CURRICULUM</span><h2>Explore your course outline</h2><p>Choose a subject and class to see the strands you will study.</p></div><a href="https://nacca.gov.gh/curriculum/" target="_blank" rel="noreferrer">Curriculum source ↗</a></div><div className="subject-selector">{(Object.keys(subjectMeta) as Subject[]).map(s=><button key={s} className={subject===s?"active":""} onClick={()=>setSubject(s)}><i className={subjectMeta[s].tone}>{subjectMeta[s].mark}</i><span><b>{subjectLabel(s)}</b><small>{subjectMeta[s].summary}</small></span><em>→</em></button>)}</div><div className="level-panel"><div className="level-picker"><span>SELECT YOUR CLASS</span>{classLevels.map(n=><button key={n} className={level===n?"active":""} onClick={()=>setLevel(n)}>Basic {n}</button>)}</div><div className="outline-panel"><div className="outline-title"><span className={`outline-mark ${subjectMeta[subject].tone}`}>{subjectMeta[subject].mark}</span><div><small>BASIC {level} · {subjectLabel(subject).toUpperCase()}</small><h3>{subjectLabel(subject)} course outline</h3><p>{level<7?"Upper Primary standards-based curriculum":"Junior High Common Core Programme"}</p></div><span className="topic-count">{topics.length} strands</span></div><div className="topic-list">{topics.map((topic,i)=><article key={topic}><span>{String(i+1).padStart(2,"0")}</span><div><b>{topic}</b><small>Lessons, activities, practice questions and assessment</small></div><button>Start strand →</button></article>)}</div><div className="curriculum-note"><b>Curriculum alignment</b><p>Outlines are organised from official NaCCA subject strands for Basic 4–6 and the Common Core Programme for Basic 7–9. Schools may sequence indicators differently by term.</p></div></div></div></section>
}

type ManagedUser={id:string;full_name:string;email:string;phone:string|null;role:string;status:string;class_level:string|null;staff_id:string|null;username:string|null;last_login_at:string|null;password_changed_at:string|null;created_at:string;teacher_assignments?:{subjects:string[];classes:string[]}[]};
function AccountManagement({initialRole}:{initialRole:string}){
  const [users,setUsers]=useState<ManagedUser[]>([]);const [search,setSearch]=useState("");const [role,setRole]=useState(initialRole);const [status,setStatus]=useState("");const [loading,setLoading]=useState(true);const [error,setError]=useState("");const [showTeacher,setShowTeacher]=useState(false);const [credentials,setCredentials]=useState<{temporaryPassword:string}|null>(null);const [page,setPage]=useState(1);const [pages,setPages]=useState(1);
  const load=async(nextPage: number | unknown=page)=>{const targetPage=typeof nextPage==="number"?nextPage:1;setLoading(true);const q=new URLSearchParams({page:String(targetPage)});if(search)q.set("search",search);if(role)q.set("role",role);if(status)q.set("status",status);const res=await fetch(`/api/admin/users?${q}`);const data=await res.json();if(res.ok){setUsers(data.users||[]);setPage(data.page||1);setPages(data.pages||1);setError("")}else setError(data.error||"Unable to load users");setLoading(false)};
  useEffect(()=>{void load()},[role,status]);
  const changeStatus=async(id:string,next:string)=>{if(!confirm(`Confirm account status change to ${next}?`))return;const res=await fetch(`/api/admin/users/${id}/status`,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({status:next})});if(res.ok)void load();else setError((await res.json()).error)};
  const changeClass=async(id:string,classLevel:string)=>{const res=await fetch(`/api/admin/users/${id}/class-level`,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({classLevel:classLevel||null})});if(res.ok)void load();else setError((await res.json()).error)};
  const editAssignment=async(user:ManagedUser)=>{const current=user.teacher_assignments?.[0];const subjects=prompt("Assigned subjects (comma separated):",current?.subjects.join(", ")||"");if(subjects===null)return;const classes=prompt("Assigned classes (comma separated):",current?.classes.join(", ")||"");if(classes===null)return;if(!confirm("Confirm this teacher assignment change?"))return;const res=await fetch(`/api/admin/users/${user.id}/assignment`,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({subjects:subjects.split(",").map(value=>value.trim()).filter(Boolean),classes:classes.split(",").map(value=>value.trim()).filter(Boolean)})});if(res.ok)void load();else setError((await res.json()).error)};
  const resetPassword=async(id:string)=>{if(!confirm("Generate a temporary password? The user must replace it after the next sign-in."))return;const res=await fetch(`/api/admin/users/${id}/temporary-password`,{method:"POST"});const data=await res.json();if(res.ok)setCredentials(data);else setError(data.error)};
  return <section className="accounts"><div className="accounts-head"><div><span className="kicker">ROLE-BASED ACCESS CONTROL</span><h1>User accounts</h1><p>Usernames and account state are visible. Current passwords remain encrypted; issue a temporary password when access must be reset.</p></div><button onClick={()=>setShowTeacher(true)}>+ Create teacher account</button></div><div className="account-filters"><label><span>Search</span><input value={search} onChange={e=>setSearch(e.target.value)} onKeyDown={e=>e.key==="Enter"&&load()} placeholder="Name, email or username"/></label><label><span>Role</span><select value={role} onChange={e=>setRole(e.target.value)}><option value="">All roles</option><option value="student">Students</option><option value="teacher">Teachers</option><option value="administrator">Administrators</option></select></label><label><span>Status</span><select value={status} onChange={e=>setStatus(e.target.value)}><option value="">All statuses</option><option value="pending_verification">Pending verification</option><option value="active">Active</option><option value="suspended">Suspended</option><option value="disabled">Disabled</option><option value="password_change_required">Password change required</option></select></label><button onClick={load}>Apply filters</button></div>{error&&<div className="account-alert error">{error}</div>}{loading?<div className="account-loading">Loading accounts…</div>:users.length===0?<div className="account-empty"><span>00</span><h3>No accounts found</h3><p>Adjust the filters or create a teacher account.</p></div>:<div className="account-table"><div className="account-row header"><span>User / Login</span><span>Role</span><span>Status / Password</span><span>Assignment / Staff ID</span><span>Last login</span><span>Actions</span></div>{users.map(u=>{const assignment=u.teacher_assignments?.[0];return <div className="account-row" key={u.id}><div className="account-person"><i>{u.full_name.split(" ").map(x=>x[0]).slice(0,2).join("")}</i><span><b>{u.full_name}</b><small>@{u.username||"no-username"} · {u.email}</small></span></div><span><em className={`role-badge ${u.role}`}>{u.role}</em></span><span className="account-state"><em className={`status-badge ${u.status}`}>{u.status.replaceAll("_"," ")}</em><small>{u.password_changed_at?`Changed ${new Date(u.password_changed_at).toLocaleDateString()}`:u.status==="password_change_required"?"Temporary password issued":"Password date unavailable"}</small></span><span className="account-assignment">{u.role==="student"?<select aria-label={`Class for ${u.full_name}`} value={u.class_level||""} onChange={event=>changeClass(u.id,event.target.value)}><option value="">Unassigned</option>{classLevels.map(value=><option key={value} value={`Basic ${value}`}>Basic {value}</option>)}</select>:assignment?<><b>{assignment.subjects.join(", ")||"No subject"}</b><small>{assignment.classes.join(", ")||u.staff_id||"No classes"}</small></>:u.staff_id||"—"}</span><span>{u.last_login_at?new Date(u.last_login_at).toLocaleDateString():"Never"}</span><div className="account-actions">{u.role==="teacher"&&<button onClick={()=>editAssignment(u)}>Edit assignment</button>}<button onClick={()=>resetPassword(u.id)}>Reset password</button>{u.status==="active"?<button className="danger" onClick={()=>changeStatus(u.id,"suspended")}>Suspend</button>:<button onClick={()=>changeStatus(u.id,"active")}>Activate</button>}</div></div>})}</div>}<div className="pagination"><button disabled={page<=1} onClick={()=>load(page-1)}>← Previous</button><span>Page {page} of {pages}</span><button disabled={page>=pages} onClick={()=>load(page+1)}>Next →</button></div>{showTeacher&&<TeacherAccountDialog close={()=>setShowTeacher(false)} created={c=>{setShowTeacher(false);setCredentials(c);void load()}}/>}{credentials&&<div className="modal-backdrop"><div className="credential-card"><button className="modal-close" onClick={()=>setCredentials(null)}>×</button><span className="kicker">ONE-TIME CREDENTIAL</span><h2>Temporary password created</h2><p>Copy this password now. Existing passwords are never retrievable.</p><code>{credentials.temporaryPassword}</code><button onClick={()=>navigator.clipboard.writeText(credentials.temporaryPassword)}>Copy password</button></div></div>}</section>
}
function TeacherAccountDialog({close,created}:{close:()=>void;created:(c:{temporaryPassword:string})=>void}){const [form,setForm]=useState({fullName:"",email:"",phone:"",staffId:"",username:"",subjects:"",classes:"",status:"password_change_required"});const [busy,setBusy]=useState(false);const [error,setError]=useState("");const set=(key:string,value:string)=>setForm({...form,[key]:value});const submit=async()=>{setBusy(true);const res=await fetch("/api/admin/users",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({...form,subjects:form.subjects.split(",").map(x=>x.trim()).filter(Boolean),classes:form.classes.split(",").map(x=>x.trim()).filter(Boolean)})});const data=await res.json();setBusy(false);if(res.ok)created(data);else setError(data.error)};return <div className="modal-backdrop" onMouseDown={close}><div className="teacher-dialog" onMouseDown={e=>e.stopPropagation()}><button className="modal-close" onClick={close}>×</button><span className="kicker">ADMINISTRATOR ONLY</span><h2>Create teacher account</h2><p>The teacher receives a temporary password and changes it once after the first sign-in.</p><div className="teacher-form">{[["fullName","Full name"],["email","Email address"],["phone","Phone number"],["staffId","Staff ID"],["username","Username"],["subjects","Assigned subjects (comma separated)"],["classes","Assigned classes (comma separated)"]].map(([key,label])=><label key={key}><span>{label}</span><input value={form[key as keyof typeof form]} onChange={e=>set(key,e.target.value)}/></label>)}</div><label className="teacher-status"><span>Account status</span><select value={form.status} onChange={e=>set("status",e.target.value)}><option value="password_change_required">Password change required</option><option value="active">Active</option><option value="suspended">Suspended</option><option value="disabled">Disabled</option></select></label>{error&&<em className="form-error">{error}</em>}<button className="button" disabled={busy} onClick={submit}>{busy?"Creating secure account…":"Create teacher account"}</button></div></div>}

type LearningMaterial={id:number;teacher_id:string;title:string;description:string|null;subject:string;class_level:string;file_name:string;mime_type:string;size_bytes:number;status:string;created_at:string;downloadUrl:string|null};
function LearningMaterialsWorkspace({role,notify}:{role:Role;notify:(message:string)=>void}){
  const [materials,setMaterials]=useState<LearningMaterial[]>([]);const [loading,setLoading]=useState(true);const [error,setError]=useState("");const [showUpload,setShowUpload]=useState(false);const [editing,setEditing]=useState<LearningMaterial|null>(null);const [busy,setBusy]=useState(false);const [form,setForm]=useState({title:"",description:"",subject:"Computing",classLevel:"Basic 7"});const [file,setFile]=useState<File|null>(null);
  const load=async()=>{setLoading(true);const response=await fetch("/api/materials");const data=await response.json();if(response.ok){setMaterials(data.materials||[]);setError("")}else setError(data.error||"Unable to load materials.");setLoading(false)};
  useEffect(()=>{void load()},[]);
  const upload=async()=>{if(!file)return;setBusy(true);setError("");const body=new FormData();Object.entries(form).forEach(([key,value])=>body.append(key,value));body.append("file",file);const response=await fetch("/api/materials",{method:"POST",body});const data=await response.json();setBusy(false);if(response.ok){setShowUpload(false);setFile(null);setForm({title:"",description:"",subject:"Computing",classLevel:"Basic 7"});notify(data.message);void load()}else setError(data.error||"Unable to upload material.")};
  const review=async(id:number,status:string)=>{const response=await fetch("/api/materials",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({id,status})});const data=await response.json();if(response.ok){notify(`Material marked ${status}.`);void load()}else setError(data.error||"Unable to review material.")};
  const startEdit=(material:LearningMaterial)=>{setEditing(material);setForm({title:material.title,description:material.description||"",subject:material.subject,classLevel:material.class_level})};
  const saveEdit=async()=>{if(!editing)return;setBusy(true);const response=await fetch("/api/materials",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:editing.id,...form})});const data=await response.json();setBusy(false);if(response.ok){setEditing(null);notify("Learning material updated.");void load()}else setError(data.error||"Unable to update material.")};
  const heading=role==="Teacher"?"Learning Resources":role==="Administrator"?"Learning Materials":"Resources";const intro=role==="Teacher"?"Upload resources and track their review status.":role==="Administrator"?"Review teacher uploads before students can access them.":"Download learning materials published for students.";
  const fields=<><label><span>Title</span><input value={form.title} onChange={event=>setForm({...form,title:event.target.value})} placeholder="e.g. Algorithms practice worksheet"/></label><div className="upload-fields"><label><span>Subject</span><select value={form.subject} onChange={event=>setForm({...form,subject:event.target.value})}>{["English Language","Mathematics","Integrated Science","Computing"].map(value=><option key={value}>{value}</option>)}</select></label><label><span>Class</span><select value={form.classLevel} onChange={event=>setForm({...form,classLevel:event.target.value})}>{classLevels.map(value=><option key={value}>Basic {value}</option>)}</select></label></div><label><span>Description</span><textarea value={form.description} onChange={event=>setForm({...form,description:event.target.value})} placeholder="What will students learn from this resource?"/></label></>;
  return <section className="materials-workspace"><div className="workspace-heading"><div><span className="kicker">PRIVATE SUPABASE STORAGE</span><h1>{heading}</h1><p>{intro}</p></div>{role!=="Student"&&<button onClick={()=>setShowUpload(true)}>+ Upload material</button>}</div>{error&&<div className="account-alert error">{error}</div>}<div className="workspace-tools"><button onClick={load}>↻ Refresh</button><span>{materials.length} material{materials.length===1?"":"s"}</span></div>{loading?<div className="account-loading">Loading learning materials…</div>:materials.length===0?<div className="account-empty"><span>00</span><h3>No learning materials yet</h3><p>{role==="Teacher"?"Upload the first resource for administrator review.":role==="Administrator"?"Teacher uploads will appear here for review.":"Published teacher resources will appear here."}</p></div>:<div className="material-grid">{materials.map(material=><article key={material.id}><div className="material-icon">{material.mime_type.includes("pdf")?"PDF":material.mime_type.startsWith("image/")?"IMG":material.mime_type.startsWith("video/")?"VID":material.mime_type.startsWith("audio/")?"AUD":"DOC"}</div><div className="material-copy"><small>{material.class_level} · {material.subject}</small><h3>{material.title}</h3><p>{material.description||material.file_name}</p><span>{(material.size_bytes/1024/1024).toFixed(2)} MB · {new Date(material.created_at).toLocaleDateString()}</span></div><em className={`material-status ${material.status}`}>{material.status}</em><div className="material-actions">{role!=="Student"&&(role==="Administrator"||material.status==="pending")&&<button onClick={()=>startEdit(material)}>Edit</button>}{material.downloadUrl&&<a href={material.downloadUrl}>Download</a>}{role==="Administrator"&&material.status==="pending"&&<><button onClick={()=>review(material.id,"published")}>Publish</button><button className="danger" onClick={()=>review(material.id,"rejected")}>Reject</button></>}</div></article>)}</div>}{showUpload&&<div className="modal-backdrop" onMouseDown={()=>!busy&&setShowUpload(false)}><div className="upload-dialog" onMouseDown={event=>event.stopPropagation()}><button className="modal-close" onClick={()=>setShowUpload(false)}>×</button><span className="kicker">STAFF UPLOAD</span><h2>Add learning material</h2><p>Files remain private and pending until an administrator publishes them.</p>{fields}<label className="file-picker"><span>{file?file.name:"Choose PDF, document, slides, image, video or audio"}</span><input type="file" accept=".pdf,.doc,.docx,.ppt,.pptx,.jpg,.jpeg,.png,.webp,.mp4,.webm,.mp3,.m4a,.wav" onChange={event=>setFile(event.target.files?.[0]||null)}/></label><small>Maximum file size: 20 MB.</small>{error&&<em className="form-error">{error}</em>}<button className="button" disabled={busy||!file||form.title.trim().length<3} onClick={upload}>{busy?"Uploading securely…":"Upload for review"}</button></div></div>}{editing&&<div className="modal-backdrop" onMouseDown={()=>!busy&&setEditing(null)}><div className="upload-dialog" onMouseDown={event=>event.stopPropagation()}><button className="modal-close" onClick={()=>setEditing(null)}>×</button><span className="kicker">EDIT MATERIAL</span><h2>Update learning material</h2><p>The stored file remains unchanged; update its title, description, subject or class.</p>{fields}{error&&<em className="form-error">{error}</em>}<button className="button" disabled={busy||form.title.trim().length<3} onClick={saveEdit}>{busy?"Saving…":"Save changes"}</button></div></div>}</section>
}

type DashboardData={viewer:{fullName:string;email:string;phone:string|null;username:string|null;classLevel:string|null;role:string;status:string;lastLoginAt:string|null};counts:{students:number;activeStudents:number;teachers:number;activeTeachers:number;pendingMaterials:number;publishedMaterials:number};assignments:{subjects:string[];classes:string[]};classCounts:{classLevel:string;count:number}[];students:{id:string;fullName:string;email:string;classLevel:string|null;status:string}[]};
export function Dashboard({role,logout}:{role:Role;logout:()=>void}){
  const nav=role==="Student"?studentNav:role==="Teacher"?teacherNav:adminNav;const [active,setActive]=useState("Dashboard");const [dark,setDark]=useState(false);const [mobile,setMobile]=useState(false);const [search,setSearch]=useState("");const [notice,setNotice]=useState("");const [dashboard,setDashboard]=useState<DashboardData|null>(null);
  useEffect(()=>{fetch("/api/dashboard").then(async response=>{if(response.ok)setDashboard(await response.json())}).catch(()=>setNotice("Unable to load live dashboard data."))},[]);
  const go=(target:string)=>{setActive(target);setMobile(false);setNotice("");window.scrollTo({top:0,behavior:"smooth"})};
  const runSearch=()=>{const match=nav.find(item=>item.toLowerCase().includes(search.trim().toLowerCase()));if(match)go(match);else setNotice(search.trim()?`No workspace matched “${search.trim()}”.`:"Type a workspace name to search.")};
  const messages=nav.includes("Messages")?"Messages":role==="Administrator"?"Security & Audit":"Dashboard";const notifications=nav.includes("Calendar")?"Calendar":role==="Administrator"?"Reports & Analytics":"Dashboard";
  return <div className={`dashboard-app ${dark?"dark":""}`}><aside className={mobile?"open":""}><Logo/><nav>{nav.map((n,i)=><button key={n} className={active===n?"active":""} onClick={()=>go(n)}><i>{String(i+1).padStart(2,"0")}</i><span>{n}</span></button>)}</nav><div className="side-access"><b>Switch portal</b><button onClick={logout}>Student account</button><button onClick={logout}>Teacher login</button><button onClick={logout}>Administrator login</button></div><button className="logout" onClick={logout}>← Sign out</button></aside><div className="workspace"><header><button className="mobile-menu" onClick={()=>setMobile(!mobile)}>☰</button><label className="search"><span>⌕</span><input value={search} onChange={event=>setSearch(event.target.value)} onKeyDown={event=>event.key==="Enter"&&runSearch()} placeholder="Search workspaces..." list="workspace-search"/><datalist id="workspace-search">{nav.map(item=><option key={item} value={item}/>)}</datalist></label><div className="top-actions"><button title="Messages" onClick={()=>go(messages)}>✉</button><button title="Notifications" onClick={()=>go(notifications)}>♢</button><button className="theme" title="Toggle colour theme" onClick={()=>setDark(!dark)}>{dark?"☀":"◐"}</button><button className="user" onClick={()=>setNotice(`${role} profile controls are available from School Settings or account management.`)}><span>{(dashboard?.viewer.fullName||dashboard?.viewer.username||role).split(" ").map(value=>value[0]).slice(0,2).join("").toUpperCase()}</span><div><b>{dashboard?.viewer.fullName||dashboard?.viewer.username||role}</b><small>{role}</small></div><i>⌄</i></button></div></header><main>{notice&&<div className="workspace-notice"><span>{notice}</span><button onClick={()=>setNotice("")}>×</button></div>}{active==="Dashboard"?<RoleDashboard role={role} navigate={go} notify={setNotice} data={dashboard}/>:active==="My Classes"&&role==="Teacher"?<ClassesWorkspace data={dashboard} navigate={go}/>:active==="My Subjects"&&role==="Teacher"?<TeacherSubjectsWorkspace data={dashboard}/>:active==="Student Lists"&&role==="Teacher"?<StudentListsWorkspace data={dashboard}/>:active==="Profile"?<ProfileWorkspace data={dashboard} notify={setNotice}/>:active==="Notifications"?<NotificationsWorkspace/>:active==="Audit Logs"&&role==="Administrator"?<AuditWorkspace/>:active==="Assessments"?<AssessmentWorkspace role={role} notify={setNotice}/>:role==="Student"&&(active==="My Courses"||active==="My Learning")?<CurriculumBrowser/>:role==="Administrator"&&["Student Management","Teacher Management","User Accounts"].includes(active)?<AccountManagement key={active} initialRole={active==="Student Management"?"student":active==="Teacher Management"?"teacher":""}/>:((role==="Teacher"&&active==="Learning Resources")||(role==="Administrator"&&active==="Learning Resources")||(role==="Student"&&active==="Learning Resources"))?<LearningMaterialsWorkspace role={role} notify={setNotice}/>:<WorkspacePanel title={active} role={role} navigate={go} notify={setNotice}/>}</main></div></div>
}

function EnrollmentNotice(){return <aside className="enrollment-notice" aria-label="Enrollment announcement"><div><span>ENROLLMENT ONGOING</span><b>Admissions remain open until 1 September 2026.</b></div><p>For more information, contact us on <a href="tel:0248274885">0248274885</a> or <a href="tel:0208678734">0208678734</a>.</p></aside>}
function RoleDashboard({role,navigate,notify,data}:{role:Role;navigate:(target:string)=>void;notify:(message:string)=>void;data:DashboardData|null}){const home=role==="Teacher"?<TeacherHome navigate={navigate} notify={notify} data={data}/>:role==="Administrator"?<AdminHome navigate={navigate} data={data}/>:<StudentHome navigate={navigate} data={data}/>;return <><EnrollmentNotice/>{home}</>}

function EmptyPanel({title,body,action,onAction}:{title:string;body:string;action?:string;onAction?:()=>void}){return <section className="dash-panel real-empty"><span>00</span><h3>{title}</h3><p>{body}</p>{action&&onAction&&<button onClick={onAction}>{action} →</button>}</section>}
function StudentHome({navigate,data}:{navigate:(target:string)=>void;data:DashboardData|null}){const name=data?.viewer.fullName||data?.viewer.username||"Student";return <><section className="dash-welcome"><div><span className="kicker">STUDENT WORKSPACE</span><h1>Welcome, {name}</h1><p>{data?.viewer.classLevel?`You are enrolled in ${data.viewer.classLevel}.`:"Your account is active. An administrator will assign your class level."}</p></div></section><section className="quick-actions"><button onClick={()=>navigate("My Courses")}><i>▶</i><span><b>My courses</b><small>Open your curriculum</small></span></button><button onClick={()=>navigate("Assessments")}><i>✓</i><span><b>Module quizzes</b><small>Take available assessments</small></span></button><button onClick={()=>navigate("Learning Resources")}><i>↓</i><span><b>Resources</b><small>{data?.counts.publishedMaterials||0} published materials</small></span></button></section><CurriculumBrowser/><div className="dashboard-grid"><EmptyPanel title="No assignments yet" body="Assignments created for your class will appear here."/><EmptyPanel title="No recent activity" body="Your completed lessons and assessments will appear here."/></div></>}
function TeacherHome({navigate,data}:{navigate:(target:string)=>void;notify:(message:string)=>void;data:DashboardData|null}){const learners=data?.classCounts.reduce((sum,item)=>sum+item.count,0)||0;const classCount=data?.assignments.classes.length||0;return <><section className="role-hero"><div><span className="kicker">TEACHER WORKSPACE</span><h1>Manage your assigned learners.</h1><p>All counts below come from enrolled student profiles and published resources.</p></div><button onClick={()=>navigate("Learning Resources")}>+ Upload learning material</button></section><div className="stat-grid"><Metric value={String(learners)} label="Enrolled learners" note={`Across ${classCount} assigned classes`}/><Metric value={String(classCount)} label="Assigned classes" note={data?.assignments.subjects.join(", ")||"No subject assignment"}/><Metric value={String(data?.counts.publishedMaterials||0)} label="Published materials" note="Available to students"/><Metric value={String(data?.counts.pendingMaterials||0)} label="Pending materials" note="Awaiting administrator review"/></div><div className="dashboard-grid"><EmptyPanel title="No assignments created" body="New assignments will appear after they are added to the platform." action="Open assignments" onAction={()=>navigate("Assignments")}/><EmptyPanel title="No submissions awaiting review" body="Student submissions will appear here when assessment submission storage is enabled."/></div></>}
function AdminHome({navigate,data}:{navigate:(target:string)=>void;data:DashboardData|null}){const destinations:Record<string,string>={"User management":"User Accounts","Academic management":"Classes","Resource library":"Learning Resources","Reports & analytics":"Reports","Security & audit":"Audit Logs"};return <><section className="role-hero admin"><div><span className="kicker">ADMINISTRATION CONTROL CENTER</span><h1>Live institution overview.</h1><p>Account and material totals are loaded from Supabase.</p></div><button onClick={()=>navigate("User Accounts")}>Manage enrollment</button></section><div className="stat-grid"><Metric value={String(data?.counts.students||0)} label="Enrolled students" note={`${data?.counts.activeStudents||0} active`}/><Metric value={String(data?.counts.teachers||0)} label="Teachers" note={`${data?.counts.activeTeachers||0} active`}/><Metric value={String(data?.counts.pendingMaterials||0)} label="Materials to review" note="Pending publication"/><Metric value={String(data?.counts.publishedMaterials||0)} label="Published materials" note="Available to students"/></div>{(data?.counts.pendingMaterials||0)===0?<EmptyPanel title="No resources awaiting review" body="Teacher uploads requiring approval will appear here." action="Open learning resources" onAction={()=>navigate("Learning Resources")}/>:<EmptyPanel title={`${data?.counts.pendingMaterials} resources awaiting review`} body="Open learning resources to publish or reject submitted resources." action="Review resources" onAction={()=>navigate("Learning Resources")}/>}<section className="management-grid">{Object.keys(destinations).map((x,i)=><button key={x} onClick={()=>navigate(destinations[x])}><i>{String(i+1).padStart(2,"0")}</i><span><b>{x}</b><small>Open management workspace</small></span><em>→</em></button>)}</section></>}
function Metric({value,label,note}:{value:string;label:string;note:string}){return <article><i>•</i><div><b>{value}</b><span>{label}</span><small>{note}</small></div></article>}

function ProfileWorkspace({data,notify}:{data:DashboardData|null;notify:(message:string)=>void}){const [fullName,setFullName]=useState("");const [phone,setPhone]=useState("");const [busy,setBusy]=useState(false);useEffect(()=>{if(data){setFullName(data.viewer.fullName);setPhone(data.viewer.phone||"")}},[data]);const save=async()=>{setBusy(true);const response=await fetch("/api/account/profile",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({fullName,phone})});const body=await response.json();setBusy(false);notify(response.ok?body.message:body.error)};return <section className="functional-workspace"><div className="workspace-heading"><div><span className="kicker">ACCOUNT PROFILE</span><h1>Profile</h1><p>Update your personal information. Roles and account status remain administrator-controlled.</p></div></div>{!data?<div className="account-loading">Loading profile…</div>:<div className="profile-form"><label>Email address<input value={data.viewer.email} disabled/></label><label>Username<input value={data.viewer.username||"Not assigned"} disabled/></label><label>Full name <b className="required">*</b><input value={fullName} onChange={event=>setFullName(event.target.value)}/></label><label>Phone number <b className="required">*</b><input value={phone} onChange={event=>setPhone(event.target.value)}/></label><label>Role<input value={data.viewer.role} disabled/></label><label>Account status<input value={data.viewer.status.replaceAll("_"," ")} disabled/></label><button className="button" disabled={busy} onClick={save}>{busy?"Saving…":"Save profile"}</button></div>}</section>}

type NotificationRow={id:number;title:string;body:string;read_at:string|null;created_at:string};
function NotificationsWorkspace(){const [items,setItems]=useState<NotificationRow[]>([]);const [loading,setLoading]=useState(true);const load=async()=>{setLoading(true);const response=await fetch("/api/notifications");if(response.ok)setItems(await response.json());setLoading(false)};useEffect(()=>{void load()},[]);const read=async(id:number)=>{await fetch("/api/notifications",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({id})});void load()};return <section className="functional-workspace"><div className="workspace-heading"><div><span className="kicker">IN-APP NOTIFICATIONS</span><h1>Notifications</h1><p>Account, assignment, assessment, and resource updates appear here.</p></div></div>{loading?<div className="account-loading">Loading notifications…</div>:items.length===0?<div className="account-empty"><span>00</span><h3>No notifications</h3><p>New system notifications will appear here.</p></div>:<div className="notification-list">{items.map(item=><button key={item.id} className={item.read_at?"read":""} onClick={()=>read(item.id)}><span/><div><b>{item.title}</b><p>{item.body}</p><small>{new Date(item.created_at).toLocaleString()}</small></div></button>)}</div>}</section>}

type AuditRow={id:number;actor_id:string|null;action:string;affected_record:string|null;ip_address:string|null;previous_value:unknown;new_value:unknown;created_at:string};
function AuditWorkspace(){const [logs,setLogs]=useState<AuditRow[]>([]);const [loading,setLoading]=useState(true);useEffect(()=>{fetch("/api/admin/audit").then(async response=>{if(response.ok)setLogs((await response.json()).logs||[])}).finally(()=>setLoading(false))},[]);return <section className="functional-workspace"><div className="workspace-heading"><div><span className="kicker">ADMINISTRATOR ONLY</span><h1>Audit Logs</h1><p>Security-sensitive account and platform actions are recorded here.</p></div></div>{loading?<div className="account-loading">Loading audit logs…</div>:logs.length===0?<div className="account-empty"><span>00</span><h3>No audit activity</h3></div>:<div className="audit-table"><div className="audit-row header"><span>Date</span><span>Action</span><span>Actor</span><span>Affected record</span><span>IP address</span></div>{logs.map(log=><div className="audit-row" key={log.id}><span>{new Date(log.created_at).toLocaleString()}</span><b>{log.action.replaceAll("_"," ")}</b><span>{log.actor_id||"System"}</span><span>{log.affected_record||"—"}</span><span>{log.ip_address||"—"}</span></div>)}</div>}</section>}

function ClassesWorkspace({data,navigate}:{data:DashboardData|null;navigate:(target:string)=>void}){const rows=data?.classCounts||[];return <section className="functional-workspace"><div className="workspace-heading"><div><span className="kicker">TEACHER WORKSPACE</span><h1>Classes</h1><p>Assigned classes and learner totals are loaded from current student enrollment records.</p></div></div><div className="workspace-tools"><button onClick={()=>location.reload()}>↻ Refresh</button><button onClick={()=>navigate("Dashboard")}>← Dashboard</button></div>{!data?<div className="account-loading">Loading enrolled classes…</div>:rows.length===0?<div className="account-empty"><span>00</span><h3>No classes assigned</h3><p>An administrator must assign classes to this teacher.</p></div>:<div className="workspace-records">{rows.map((row,index)=><button key={row.classLevel} onClick={()=>navigate("Student Performance")}><i>{String(index+1).padStart(2,"0")}</i><span><b>{row.classLevel}</b><small>{row.count} enrolled learner{row.count===1?"":"s"}</small></span><em>Open →</em></button>)}</div>}</section>}

function TeacherSubjectsWorkspace({data}:{data:DashboardData|null}){const subjects=data?.assignments.subjects||[];return <section className="functional-workspace"><div className="workspace-heading"><div><span className="kicker">TEACHER ASSIGNMENT</span><h1>My Subjects</h1><p>Only subjects assigned by the administrator are shown.</p></div></div>{!data?<div className="account-loading">Loading subjects…</div>:subjects.length===0?<div className="account-empty"><span>00</span><h3>No subjects assigned</h3></div>:<div className="workspace-records">{subjects.map((subject,index)=><button key={subject}><i>{String(index+1).padStart(2,"0")}</i><span><b>{subject}</b><small>{data.assignments.classes.join(", ")}</small></span></button>)}</div>}</section>}
function StudentListsWorkspace({data}:{data:DashboardData|null}){const students=data?.students||[];return <section className="functional-workspace"><div className="workspace-heading"><div><span className="kicker">ASSIGNED CLASSES ONLY</span><h1>Student Lists</h1><p>Students outside your assigned classes are excluded by the server.</p></div></div>{!data?<div className="account-loading">Loading students…</div>:students.length===0?<div className="account-empty"><span>00</span><h3>No enrolled students in assigned classes</h3></div>:<div className="student-list">{students.map(student=><article key={student.id}><span>{student.fullName.split(" ").map(value=>value[0]).slice(0,2).join("")}</span><div><b>{student.fullName}</b><small>{student.classLevel} · {student.email}</small></div><em className={`status-badge ${student.status}`}>{student.status.replaceAll("_"," ")}</em></article>)}</div>}</section>}

function AssessmentWorkspace({role}:{role:Role;notify:(message:string)=>void}){
  const [subject,setSubject]=useState<Subject>("English");const [level,setLevel]=useState(7);const [kind,setKind]=useState<"quiz"|"practical">("quiz");const [module,setModule]=useState(0);
  const modules=curriculum[subject][level];const current=modules[module]||modules[0];const subjectLabel=subject==="English"?"English Language":subject==="Science"?"Integrated Science":subject;
  const chooseModule=(index:number)=>setModule(index);
  const emptyTitle=kind==="quiz"?"No quiz published for this module":"No practical assessment published for this module";
  const emptyBody=role==="Student"?"Your teacher will publish this assessment when it is ready.":"Assessment authoring is not yet connected. No sample questions are being shown.";
  return <section className="assessment-workspace"><div className="workspace-heading"><div><span className="kicker">MODULE-BASED ASSESSMENT</span><h1>Assessments</h1><p>Every sub-strand is one module, with a quiz at the end of that module.</p></div></div><div className="assessment-filters"><label><span>Subject</span><select value={subject} onChange={event=>{setSubject(event.target.value as Subject);chooseModule(0)}}>{(["English","Mathematics","Science","Computing"] as Subject[]).map(value=><option key={value} value={value}>{value==="English"?"English Language":value==="Science"?"Integrated Science":value}</option>)}</select></label><label><span>Class</span><select value={level} onChange={event=>{setLevel(Number(event.target.value));chooseModule(0)}}>{classLevels.map(value=><option key={value} value={value}>Basic {value}</option>)}</select></label></div><div className="assessment-types"><button className={kind==="quiz"?"active":""} onClick={()=>setKind("quiz")}><b>Module quizzes</b><small>A quiz becomes available at the end of every sub-strand module.</small></button><button className={kind==="practical"?"active":""} onClick={()=>setKind("practical")}><b>Practical assessments</b><small>Practical work published for the selected module appears here.</small></button></div><div className="assessment-layout"><nav className="module-list" aria-label="Sub-strand modules"><span>SUB-STRAND MODULES</span>{modules.map((value,index)=><button key={value} className={module===index?"active":""} onClick={()=>chooseModule(index)}><i>{String(index+1).padStart(2,"0")}</i><span><b>Module {index+1}</b><small>{value}</small></span></button>)}</nav><article className="assessment-detail"><span className="kicker">BASIC {level} · {subjectLabel.toUpperCase()}</span><h2>{current}</h2><p className="module-caption">Module {module+1} · Sub-strand assessment</p><div className="account-empty"><span>00</span><h3>{emptyTitle}</h3><p>{emptyBody}</p></div></article></div></section>
}

function WorkspacePanel({title,role,navigate}:{title:string;role:Role;navigate:(target:string)=>void;notify:(message:string)=>void}){return <section className="functional-workspace"><div className="workspace-heading"><div><span className="kicker">{role.toUpperCase()} WORKSPACE</span><h1>{title}</h1><p>This workspace is ready for real records. Demo entries have been removed.</p></div></div><div className="workspace-tools"><button onClick={()=>navigate("Dashboard")}>← Dashboard</button></div><div className="account-empty"><span>00</span><h3>No {title.toLowerCase()} records yet</h3><p>Records created through a connected workflow will appear here.</p></div></section>}

export default function Home(){const [auth,setAuth]=useState<{role:Role;mode:Exclude<AuthMode,null>}|null>(null);const [role,setRole]=useState<Role|null>(null);return <>{role?<Dashboard role={role} logout={()=>setRole(null)}/>:<Landing openAuth={(r,m)=>setAuth({role:r,mode:m})}/>} {auth&&<AuthDialog role={auth.role} mode={auth.mode} close={()=>setAuth(null)} enter={r=>{setRole(r);setAuth(null)}}/>}</>}
